import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001/api';

// 获取请求头配置
const getConfig = () => {
  const token = localStorage.getItem('token');
  return {
    headers: {
      Authorization: token ? `Bearer ${token}` : ''
    }
  };
};

// 获取所有手机商品
const getAllPhones = async () => {
  try {
    const response = await axios.get(`${API_URL}/phones`, getConfig());
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '获取商品列表失败';
  }
};

// 获取单个手机商品详情
const getPhoneById = async (id) => {
  try {
    const response = await axios.get(`${API_URL}/phones/${id}`, getConfig());
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '获取商品详情失败';
  }
};

// 添加到收藏
const addToFavorite = async (phoneId) => {
  try {
    const response = await axios.post(
      `${API_URL}/phones/${phoneId}/favorite`,
      {},
      getConfig()
    );
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '添加到收藏失败';
  }
};

// 从收藏中移除
const removeFromFavorite = async (phoneId) => {
  try {
    const response = await axios.delete(
      `${API_URL}/phones/${phoneId}/favorite`,
      getConfig()
    );
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '从收藏中移除失败';
  }
};

// 添加新手机商品 (仅管理员)
const createPhone = async (phoneData) => {
  try {
    const formData = new FormData();
    Object.keys(phoneData).forEach(key => {
      if (key === 'images') {
        phoneData[key].forEach(image => {
          if (image instanceof File) {
            formData.append('images', image);
          }
        });
      } else {
        formData.append(key, phoneData[key]);
      }
    });

    const config = {
      ...getConfig(),
      headers: {
        ...getConfig().headers,
        'Content-Type': 'multipart/form-data'
      }
    };

    const response = await axios.post(`${API_URL}/phones`, formData, config);
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '添加商品失败';
  }
};

// 更新手机信息
const updatePhone = async (id, phoneData) => {
  try {
    const formData = new FormData();
    Object.keys(phoneData).forEach(key => {
      if (key === 'images') {
        phoneData[key].forEach(image => {
          if (image instanceof File) {
            formData.append('images', image);
          }
        });
      } else {
        formData.append(key, phoneData[key]);
      }
    });

    const config = {
      ...getConfig(),
      headers: {
        ...getConfig().headers,
        'Content-Type': 'multipart/form-data'
      }
    };

    const response = await axios.put(`${API_URL}/phones/${id}`, formData, config);
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '更新商品失败';
  }
};

// 删除手机
const deletePhone = async (id) => {
  try {
    const response = await axios.delete(`${API_URL}/phones/${id}`, getConfig());
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '删除商品失败';
  }
};

const phoneService = {
  getAllPhones,
  getPhoneById,
  addToFavorite,
  removeFromFavorite,
  createPhone,
  updatePhone,
  deletePhone
};

export default phoneService;
